  const resource=await readNativeMedia(params=>bridge.readServerResource(params),name,options);
  if(!resource.blob)throw new Error('Preview is empty');
  const mime=resource.mimeType||(/\.mp4$/.test(name)?'video/mp4':'image/jpeg');
